export type Placement = "top" | "bottom" | "left" | "right";

/** Calls `done` once the user has completed the step; returns a cleanup. */
export type WatchDone = (done: () => void) => () => void;

export type TourStep = {
  id: string;
  title: string;
  body: string;
  /** CSS selector to spotlight. Without one the step shows as a floating card. */
  target?: string;
  placement?: Placement;
  /** Without one the step advances only through the Next button. */
  watchDone?: WatchDone;
  /** Obsidian basics that users who already know Obsidian can skip. */
  basics?: boolean;
};

// Delegated from the document so the step still completes if Obsidian re-renders the target.
export const doneOnClick =
  (selector: string): WatchDone =>
  (done) => {
    const handleClick = (event: MouseEvent): void => {
      if (event.target instanceof Element && event.target.closest(selector)) {
        done();
      }
    };
    document.addEventListener("click", handleClick, { capture: true });
    return () =>
      document.removeEventListener("click", handleClick, { capture: true });
  };

export const doneWhenPresent =
  (selector: string): WatchDone =>
  (done) => {
    if (document.querySelector(selector)) {
      done();
      return () => {};
    }
    const observer = new MutationObserver(() => {
      if (!document.querySelector(selector)) return;
      observer.disconnect();
      done();
    });
    observer.observe(document.body, { childList: true, subtree: true });
    return () => observer.disconnect();
  };

import type { TourStep } from "./tourSteps";

export type StepOutcome = "done" | "skipped";

export type TourState = {
  steps: TourStep[];
  outcomes: StepOutcome[];
};

export const createTourState = ({
  steps,
  includeBasics,
}: {
  steps: TourStep[];
  includeBasics: boolean;
}): TourState => ({
  steps: includeBasics ? steps : steps.filter((step) => !step.basics),
  outcomes: [],
});

export const getCurrentStep = (state: TourState): TourStep | undefined =>
  state.steps[state.outcomes.length];

export const isTourFinished = (state: TourState): boolean =>
  state.outcomes.length >= state.steps.length;

export const recordOutcome = (
  state: TourState,
  outcome: StepOutcome,
): TourState =>
  isTourFinished(state)
    ? state
    : { ...state, outcomes: [...state.outcomes, outcome] };

import type { Placement } from "./tourSteps";

export type Rect = { top: number; left: number; width: number; height: number };
type Size = { width: number; height: number };

export const SPOTLIGHT_PADDING = 6;
const GAP = 12;
const VIEWPORT_MARGIN = 8;

const clamp = (value: number, min: number, max: number): number =>
  Math.min(Math.max(value, min), Math.max(min, max));

/** Places the card beside the spotlight, then keeps it fully inside the viewport. */
export const getCardPosition = ({
  target,
  placement,
  card,
  viewport,
}: {
  target: Rect;
  placement: Placement;
  card: Size;
  viewport: Size;
}): { top: number; left: number } => {
  const offset = SPOTLIGHT_PADDING + GAP;
  const unclamped = {
    right: { top: target.top, left: target.left + target.width + offset },
    left: { top: target.top, left: target.left - offset - card.width },
    bottom: { top: target.top + target.height + offset, left: target.left },
    top: { top: target.top - offset - card.height, left: target.left },
  }[placement];
  return {
    top: clamp(
      unclamped.top,
      VIEWPORT_MARGIN,
      viewport.height - card.height - VIEWPORT_MARGIN,
    ),
    left: clamp(
      unclamped.left,
      VIEWPORT_MARGIN,
      viewport.width - card.width - VIEWPORT_MARGIN,
    ),
  };
};

import { doneOnClick, doneWhenPresent, type TourStep } from "./tourSteps";

const DISCOURSE_CONTEXT_RIBBON =
  '.side-dock-ribbon-action[aria-label="Toggle discourse context"]';
const COMMAND_PALETTE = ".prompt";

/** The hand-written tour from eng-1505, kept to exercise the engine before AI generation exists. */
export const SAMPLE_TOUR: TourStep[] = [
