// M1: sample tutorial engine in real Obsidian.
const RIBBON = '.side-dock-ribbon-action[aria-label="Toggle discourse context"]';
const CARD = ".dg-tutorial-card";
const SPOT = ".dg-tutorial-spotlight";

const startTour = async ({ client, json, vault }) => {
  await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:play-sample-tutorial`)});`);
  await client.waitFor(`!!document.querySelector(${json(CARD)})`, { label: "tour card rendered" });
};

const cardTitle = ({ client, json }) =>
  client.evaluate(`return document.querySelector(${json(CARD)})?.firstElementChild?.textContent ?? null;`);

const waitTitle = ({ client, json }, title) =>
  client.waitFor(`document.querySelector(${json(CARD)})?.firstElementChild?.textContent === ${json(title)}`, {
    label: `card "${title}"`,
  });

const rectOf = ({ client, json }, sel) =>
  client.evaluate(`const r = document.querySelector(${json(sel)})?.getBoundingClientRect();
    return r ? { top: Math.round(r.top), left: Math.round(r.left), width: Math.round(r.width), height: Math.round(r.height) } : null;`);

const realClick = async (ctx, sel) => {
  const r = await rectOf(ctx, sel);
  if (!r) throw new Error(`no element for ${sel}`);
  const x = r.left + r.width / 2;
  const y = r.top + r.height / 2;
  for (const type of ["mousePressed", "mouseReleased"]) {
    await ctx.client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1 });
  }
};

const clickButton = (ctx, label) =>
  ctx.client.evaluate(`const b = Array.from(document.querySelectorAll(${ctx.json(`${CARD} button`)}))
    .find((el) => el.textContent === ${ctx.json(label)}); b?.click(); return !!b;`);

const buttons = ({ client, json }) =>
  client.evaluate(`return Array.from(document.querySelectorAll(${json(`${CARD} button`)})).map((b) => b.textContent);`);

const endTour = async (ctx) => {
  await clickButton(ctx, "End tour");
  await ctx.client.waitFor(`!document.querySelector(${ctx.json(CARD)})`, { label: "tour gone" });
};

const cmdP = (client) =>
  client.key({ key: "p", code: "KeyP", windowsVirtualKeyCode: 80, nativeVirtualKeyCode: 80, modifiers: 4 });

const closeContextView = ({ client }) =>
  client.evaluate(`app.workspace.getLeavesOfType("discourse-context-view").forEach((l) => l.detach()); return true;`);

export default [
  {
    name: "Step 1 spotlights the telescope ribbon icon",
    input: "run Play sample tutorial (dev)",
    expected: "spotlight surrounds the telescope icon; card sits to its right, inside the viewport",
    run: async (ctx) => {
      await startTour(ctx);
      await ctx.client.waitFor(`!!document.querySelector(${ctx.json(SPOT)})`, { label: "spotlight" });
      return {
        title: await cardTitle(ctx),
        ribbon: await rectOf(ctx, RIBBON),
        spot: await rectOf(ctx, SPOT),
        card: await rectOf(ctx, CARD),
        buttons: await buttons(ctx),
        vw: await ctx.client.evaluate(`return window.innerWidth;`),
      };
    },
    expect: (a) => {
      const surrounds =
        a.spot.left <= a.ribbon.left && a.spot.top <= a.ribbon.top &&
        a.spot.left + a.spot.width >= a.ribbon.left + a.ribbon.width &&
        a.spot.top + a.spot.height >= a.ribbon.top + a.ribbon.height;
      const cardRight = a.card.left >= a.ribbon.left + a.ribbon.width && a.card.left + a.card.width <= a.vw;
      return {
        pass: a.title === "Discourse context panel" && surrounds && cardRight,
        actual: `title=${a.title}; spot surrounds=${surrounds}; card right & on-screen=${cardRight}; buttons=${a.buttons.join("/")}`,
      };
    },
    teardown: endTour,
  },
  {
    name: "Clicking the icon advances to the floating palette card",
    input: "start tour; real mouse click on the telescope icon",
    expected: "discourse context opens; card becomes 'Open the command palette', floating bottom-right, no spotlight; basics step offers 'Skip, I know this'",
    run: async (ctx) => {
      await startTour(ctx);
      await realClick(ctx, RIBBON);
      await waitTitle(ctx, "Open the command palette");
      return ctx.client.evaluate(`const c = document.querySelector(${ctx.json(CARD)});
        const r = c.getBoundingClientRect();
        return { floating: c.classList.contains("dg-tutorial-card--floating"),
          spot: !!document.querySelector(${ctx.json(SPOT)}),
          contextOpen: app.workspace.getLeavesOfType("discourse-context-view").length > 0,
          bottomRight: r.right > window.innerWidth - 60 && r.bottom > window.innerHeight - 60,
          buttons: Array.from(c.querySelectorAll("button")).map((b) => b.textContent) };`);
    },
    expect: (a) => ({
      pass: a.floating && !a.spot && a.contextOpen && a.bottomRight && a.buttons.includes("Skip, I know this"),
      actual: JSON.stringify(a),
    }),
    teardown: async (ctx) => {
      await endTour(ctx);
      await closeContextView(ctx);
    },
  },
  {
    name: "Cmd+P works during the tour and advances to the palette spotlight",
    input: "start tour; click icon; press Cmd+P",
    expected: "palette opens (tour's keymap scope doesn't swallow hotkeys); spotlight surrounds .prompt; Finish button",
    run: async (ctx) => {
      await startTour(ctx);
      await realClick(ctx, RIBBON);
      await waitTitle(ctx, "Open the command palette");
      await cmdP(ctx.client);
      await waitTitle(ctx, "Create a discourse node");
      await ctx.client.waitFor(`!!document.querySelector(${ctx.json(SPOT)})`, { label: "spotlight" });
      return { prompt: await rectOf(ctx, ".prompt"), spot: await rectOf(ctx, SPOT), buttons: await buttons(ctx) };
    },
    expect: (a) => {
      const surrounds = a.prompt && a.spot.left <= a.prompt.left && a.spot.top <= a.prompt.top &&
        a.spot.left + a.spot.width >= a.prompt.left + a.prompt.width;
      return { pass: !!surrounds && a.buttons.includes("Finish"), actual: `surrounds=${!!surrounds}; buttons=${a.buttons.join("/")}` };
    },
    teardown: async (ctx) => {
      await ctx.client.pressEscape();
      await endTour(ctx);
      await closeContextView(ctx);
    },
  },
  {
    name: "Escape closes the palette but keeps the tour; missing target falls back",
    input: "reach step 3 (palette open); press Escape once",
    expected: "palette closes; tour card stays; after the grace period it shows the not-on-screen note with Skip + Mark done",
    run: async (ctx) => {
      await startTour(ctx);
      await realClick(ctx, RIBBON);
      await waitTitle(ctx, "Open the command palette");
      await cmdP(ctx.client);
      await waitTitle(ctx, "Create a discourse node");
      await ctx.client.pressEscape();
      await ctx.client.waitFor(`!document.querySelector(".prompt")`, { label: "palette closed" });
      await ctx.client.waitFor(`Array.from(document.querySelectorAll(${ctx.json(`${CARD} button`)})).some((b) => b.textContent === "Mark done")`, { label: "fallback" });
      return { title: await cardTitle(ctx), buttons: await buttons(ctx), spot: !!(await rectOf(ctx, SPOT)) };
    },
    expect: (a) => ({
      pass: a.title === "Create a discourse node" && a.buttons.includes("Skip") && a.buttons.includes("Mark done") && !a.spot,
      actual: `title=${a.title}; buttons=${a.buttons.join("/")}; spotlight=${a.spot}`,
    }),
    teardown: async (ctx) => {
      await endTour(ctx);
      await closeContextView(ctx);
    },
  },
  {
    name: "Escape with nothing open ends the tour and releases the scope",
    input: "start tour; press Escape; then press Cmd+P",
    expected: "overlay and its container removed; Cmd+P still opens the palette afterwards",
    run: async (ctx) => {
      await startTour(ctx);
      const before = await ctx.client.evaluate(`return document.body.children.length;`);
      await ctx.client.pressEscape();
      await ctx.client.waitFor(`!document.querySelector(${ctx.json(CARD)})`, { label: "tour gone" });
      const after = await ctx.client.evaluate(`return document.body.children.length;`);
      await cmdP(ctx.client);
      await ctx.client.waitFor(`!!document.querySelector(".prompt")`, { label: "palette opens" });
      return { removedContainer: before - after, scopeIsApp: await ctx.client.evaluate(`return app.keymap.scope === app.scope;`) };
    },
    expect: (a) => ({ pass: a.removedContainer === 1, actual: JSON.stringify(a) }),
    teardown: (ctx) => ctx.client.pressEscape(),
  },
  {
    name: "Hidden ribbon: step 1 falls back, Mark done advances",
    input: "hide the ribbon (showRibbon=false); start tour; wait; click Mark done",
    expected: "no spotlight; not-on-screen note with Skip + Mark done; Mark done moves to step 2",
    setup: async ({ client }) => {
      const saved = await client.evaluate(`return app.vault.getConfig("showRibbon");`);
      await client.evaluate(`app.vault.setConfig("showRibbon", false); return true;`);
      return { saved };
    },
    run: async (ctx) => {
      await startTour(ctx);
      await ctx.client.waitFor(`Array.from(document.querySelectorAll(${ctx.json(`${CARD} button`)})).some((b) => b.textContent === "Mark done")`, { label: "fallback" });
      const fallback = { buttons: await buttons(ctx), spot: !!(await rectOf(ctx, SPOT)) };
      await clickButton(ctx, "Mark done");
      await waitTitle(ctx, "Open the command palette");
      return { ...fallback, next: await cardTitle(ctx) };
    },
    expect: (a) => ({
      pass: !a.spot && a.buttons.includes("Skip") && a.buttons.includes("Mark done") && a.next === "Open the command palette",
      actual: JSON.stringify(a),
    }),
    teardown: async (ctx, state) => {
      await endTour(ctx);
      await ctx.client.evaluate(`app.vault.setConfig("showRibbon", ${ctx.json(state?.saved ?? true)}); return true;`);
    },
  },
  {
    name: "Plugin reload removes an in-progress tour",
    input: "start tour; reload the plugin",
    expected: "no tutorial card or spotlight left in the DOM; scope released",
    run: async (ctx) => {
      await startTour(ctx);
      await ctx.client.reloadPlugin();
      return ctx.client.evaluate(`return { card: !!document.querySelector(${ctx.json(CARD)}),
        spot: !!document.querySelector(${ctx.json(SPOT)}), scopeIsApp: app.keymap.scope === app.scope };`);
    },
    expect: (a) => ({ pass: !a.card && !a.spot, actual: JSON.stringify(a) }),
  },
];

