const CARD = ".dg-tutorial-card";
const title = (c) => c.evaluate(`return document.querySelector(".dg-tutorial-card")?.firstElementChild?.textContent ?? null;`);
const waitTitle = (c, t) => c.waitFor(`document.querySelector(".dg-tutorial-card")?.firstElementChild?.textContent === ${JSON.stringify(t)}`, { label: t });
const cmdP = (c) => c.key({ key: "p", code: "KeyP", windowsVirtualKeyCode: 80, nativeVirtualKeyCode: 80, modifiers: 4 });

export default {
  name: "Sample tutorial: palette → create Claim → open context → done",
  input: "play sample; Cmd+P; create a Claim file (vault.create + nodeTypeId, as createDiscourseNodeFile does); close context first then click telescope; Finish",
  expected: "each block step completes from the real action; ends on the text step; create-node command callback restored",
  setup: async ({ client }) =>
    client.evaluate(`app.workspace.getLeavesOfType("discourse-context-view").forEach((l) => l.detach()); return true;`),
  run: async (ctx) => {
    const { client, json, vault } = ctx;
    await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:play-sample-tutorial`)});`);
    await waitTitle(client, "Open the command palette");
    await cmdP(client);
    await waitTitle(client, "Capture your first claim");
    await client.pressEscape();
    const path = `_verify/${ctx.branch}/CLM - tutorial spike ${Date.now()}.md`;
    await client.evaluate(`return (async () => {
      const claim = app.plugins.plugins[${json(vault.pluginId)}].settings.nodeTypes.find((t) => t.name === "Claim");
      const f = await app.vault.create(${json(path)}, "");
      await app.fileManager.processFrontMatter(f, (fm) => { fm.nodeTypeId = claim.id; });
      return true; })();`);
    await waitTitle(client, "See the claim's context");
    const r = await client.evaluate(`const el = document.querySelector('.side-dock-ribbon-action[aria-label="Toggle discourse context"]').getBoundingClientRect(); return { x: el.left + el.width / 2, y: el.top + el.height / 2 };`);
    for (const type of ["mousePressed", "mouseReleased"]) await client.send("Input.dispatchMouseEvent", { type, x: r.x, y: r.y, button: "left", clickCount: 1 });
    await waitTitle(client, "You're set up");
    const buttons = await client.evaluate(`return [...document.querySelectorAll(".dg-tutorial-card button")].map((b) => b.textContent);`);
    return { last: await title(client), buttons };
  },
  expect: (a) => ({ pass: a.last === "You're set up" && a.buttons.includes("Finish"), actual: JSON.stringify(a) }),
  teardown: async ({ client }) => client.evaluate(`[...document.querySelectorAll(".dg-tutorial-card button")].find((b) => b.textContent === "End tour")?.click(); return true;`),
};
